DROP TABLE IF EXISTS `dividend`;
CREATE TABLE `dividend` (
  `div_id` int(11) NOT NULL auto_increment,
  `div_no` int(11) NOT NULL,
  `div_rate` double(30,4) NOT NULL,
  `div_money` double(30,4) NOT NULL,
  `acc_year_id` char(4) NOT NULL,
  `user_id` int(10) NOT NULL,
  `branch_num` char(2) NOT NULL default '00',
  `dividend_status` char(1) NOT NULL,
  PRIMARY KEY  (`div_id`),
  KEY `acc_year_id` USING BTREE (`acc_year_id`),
  KEY `branch_num` USING BTREE (`branch_num`),
  KEY `user_id` USING BTREE (`user_id`)
) ENGINE=MyISAM AUTO_INCREMENT=16 DEFAULT CHARSET=tis620;

