--
-- Table structure for table `mem_member_status`
--

DROP TABLE IF EXISTS `mem_member_status`;
CREATE TABLE `mem_member_status` (
  `member_status` int(11) NOT NULL,
  `member_status_detail` varchar(255) NOT NULL,
  PRIMARY KEY  (`member_status`)
) ENGINE=MyISAM DEFAULT CHARSET=tis620;

