--
-- Table structure for table `mem_member_true`
--

DROP TABLE IF EXISTS `mem_member_true`;
CREATE TABLE `mem_member_true` (
  `member_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `member_code` char(13) NOT NULL COMMENT 'Text For Show In web',
  `head_status` int(1) NOT NULL COMMENT '0=ไม่เลือก,1=เข้าบัญชีสหกรณ์,2=เข้าบัญชีธกส.,3=จ่ายเป็นเงินสด,4=โอนเป็นหุ้น',
  `member_status` varchar(255) NOT NULL,
  `acc_operate_id` char(9) NOT NULL default '000000000',
  `member_openacc_date` date NOT NULL default '0000-00-00' COMMENT 'Date to input Member Data',
  `member_type` int(1) NOT NULL COMMENT 'สามัญ  = 1 สมทบ  = 2',
  `mem_font_name_id` int(11) NOT NULL default '0' COMMENT 'รหัสจากตาราง mem_font_name',
  `member_name` varchar(100) character set tis620 collate tis620_bin NOT NULL default '',
  `member_surname` varchar(100) character set tis620 collate tis620_bin NOT NULL default '',
  `mem_group_mem_id` int(11) NOT NULL COMMENT 'Id From mem_group_mem ',
  `member_gender` int(1) NOT NULL default '0' COMMENT '1 = ชาย 2 = หญิง',
  `member_marriage` int(1) NOT NULL,
  `member_idcard` varchar(13) NOT NULL default '',
  `member_address` varchar(255) NOT NULL default '',
  `member_mou` varchar(5) NOT NULL default '',
  `member_street` varchar(100) NOT NULL default '',
  `province_id` int(11) NOT NULL COMMENT 'From Province',
  `amphur_id` int(11) NOT NULL COMMENT 'From Amphur',
  `tumbon_id` int(11) NOT NULL COMMENT 'From Tumbon',
  `member_zipcode` varchar(5) NOT NULL,
  `member_phone` varchar(25) NOT NULL COMMENT 'From mem_level_debtor',
  `member_fax` varchar(25) NOT NULL,
  `mem_job_name_id` int(11) NOT NULL COMMENT 'Id จากตาราง mem_job_name',
  `member_money` double(30,4) NOT NULL,
  `member_money2` double(30,4) NOT NULL,
  `member_self_land` int(1) NOT NULL COMMENT 'มีที่ของสมาชิกเอง = 1 ',
  `member_rent_land` int(1) NOT NULL COMMENT 'มีการเช่าที่ดิน = 1',
  `member_other_land` int(1) NOT NULL COMMENT 'อื่นๆ = 1 ',
  `self_land_1` int(3) NOT NULL,
  `self_land_2` int(1) NOT NULL,
  `self_land_3` int(2) NOT NULL,
  `rent_land_1` int(3) NOT NULL,
  `rent_land_2` int(1) NOT NULL,
  `rent_land_3` int(2) NOT NULL,
  `about_other_land` varchar(255) NOT NULL,
  `level_debtor_id` double NOT NULL COMMENT 'จากตาราง mem_level_debtor',
  `member_limit` double(30,4) NOT NULL COMMENT 'วงเงินซื้อเชื่อ ',
  `branch_num` char(2) NOT NULL default '00',
  `user_id` int(11) NOT NULL,
  `member_images` varchar(255) NOT NULL,
  `member_birthday` date NOT NULL,
  `id_register` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `member_email` varchar(50) NOT NULL,
  `member_stock_billing` double(30,4) NOT NULL,
  `member_stock_start` date NOT NULL,
  `member_about_bank` int(1) NOT NULL,
  `deff_group_mem_billing` int(1) NOT NULL,
  `group_mem_billing_1` int(3) NOT NULL,
  `group_mem_billing_2` int(3) NOT NULL,
  `group_mem_billing_3` int(3) NOT NULL,
  `group_mem_billing_4` int(3) NOT NULL,
  `member_code_reference` varchar(100) NOT NULL,
  `bank_account_type1_reference` varchar(100) default NULL,
  `bank_account_type1_number` varchar(100) default NULL,
  `bank_account_type2_number` varchar(100) default NULL,
  `stock_code` varchar(255) NOT NULL,
  `marriage_font_name_id` int(11) NOT NULL default '0',
  `marriage_name` varchar(100) NOT NULL default '',
  `marriage_surname` varchar(100) NOT NULL default '',
  `member_son` int(5) NOT NULL default '0',
  `member_education` int(5) NOT NULL default '0',
  `member_education_other` varchar(100) NOT NULL default '',
  `inventory_get` char(1) NOT NULL default 'N',
  `time_update` timestamp NULL default NULL on update CURRENT_TIMESTAMP,
  `headoffice_sts` int(11) NOT NULL,
  `nationality` varchar(50) NOT NULL,
  PRIMARY KEY  (`member_id`),
  KEY `member_code` USING BTREE (`member_code`),
  KEY `acc_operate_id` USING BTREE (`acc_operate_id`),
