--
-- Table structure for table `mem_organization`
--

DROP TABLE IF EXISTS `mem_organization`;
CREATE TABLE `mem_organization` (
  `organization_id` int(10) NOT NULL auto_increment,
  `branch_num` char(2) NOT NULL default '00',
  `organization_code` varchar(100) NOT NULL default '0',
  `organization_name` varchar(150) NOT NULL default '',
  `organization_date_regis` date NOT NULL default '0000-00-00',
  `organization_address` varchar(255) NOT NULL default '',
  `organization_province` varchar(5) NOT NULL default '',
  `organization_amphur` varchar(50) NOT NULL default '',
  `organization_tumbon` varchar(5) NOT NULL default '',
  `organization_zipcode` varchar(5) NOT NULL default '',
  `organization_tel` varchar(25) NOT NULL default '',
  `organization_fax` varchar(25) NOT NULL default '',
  `id_taxcard` varchar(15) NOT NULL default '',
  `in_tax_check` varchar(5) NOT NULL default '',
  `in_tax_percent` varchar(50) NOT NULL,
  `last_member_data` int(11) NOT NULL,
  `head_office_status` int(1) NOT NULL default '0' COMMENT '1=head 0=none',
  `organization_detail_record` timestamp NOT NULL default CURRENT_TIMESTAMP on update CURRENT_TIMESTAMP,
  `mem_type` char(1) NOT NULL,
  `loan_status` char(1) NOT NULL,
  `inv_host` varchar(50) NOT NULL,
  `dep_host` varchar(50) NOT NULL,
  `gl_host` varchar(50) NOT NULL,
  `register_billing_use` int(1) NOT NULL,
  `register_billing_value` double(30,4) NOT NULL,
  `use_billing_1` int(1) NOT NULL,
  `select_billing_1` int(5) NOT NULL,
  `text_billing_1` int(5) NOT NULL,
  `use_billing_2` int(1) NOT NULL,
  `select_billing_2` int(5) NOT NULL,
  `text_billing_2` int(5) NOT NULL,
  `use_billing_3` int(1) NOT NULL,
  `select_billing_3` int(5) NOT NULL,
  `text_billing_3` int(5) NOT NULL,
  `use_billing_4` int(1) NOT NULL,
  `select_billing_4` int(5) NOT NULL,
  `text_billing_4` int(5) NOT NULL,
  `min_capital` double(30,0) NOT NULL default '0',
  `min_capital2` double(30,0) NOT NULL,
  `Manager` varchar(255) NOT NULL,
  `Payee` varchar(255) NOT NULL,
  `Examiner` varchar(255) NOT NULL,
  `loan_rate_use` char(1) default NULL,
  `stock_type` char(1) NOT NULL default '1',
  `convert_date` date NOT NULL default '0000-00-00',
  `confirm_stock` char(1) default 'N',
  `confirm_capital` char(1) default 'N',
  `confirm_fee` char(1) default 'N',
  `loan_host` varchar(50) default NULL,
  `organization_code_digits` varchar(13) default NULL,
  PRIMARY KEY  (`organization_id`),
  KEY `branch_num` USING BTREE (`branch_num`),
