--
-- Table structure for table `mem_receipt`
--

DROP TABLE IF EXISTS `mem_receipt`;
CREATE TABLE `mem_receipt` (
  `receipt_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `receipt_no` varchar(255) NOT NULL,
  `acc_operate_id` char(9) NOT NULL default '000000000',
  `member_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `receipt_status` int(11) NOT NULL,
  `receipt_type` varchar(10) NOT NULL,
  `receipt_id_input` int(11) NOT NULL,
  `receipt_amount` double(30,4) NOT NULL,
  `receipt_vat` double(30,4) NOT NULL default '0.0000',
  `print_count` int(11) NOT NULL,
  `description` longtext NOT NULL,
  `branch_num` char(2) NOT NULL default '00',
  `user_id` int(10) NOT NULL,
  `status_to_pay` int(10) NOT NULL default '0' COMMENT '3=ออกใบเรียกเก็บ2=จ่ายเงินแล้วอนุมัติแล้ว 1=จ่ายเงินแล้วรออนุมัติ 0=จ่ายแล้ว',
  `cancle_receipt_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `cancle_operate_id` char(9) NOT NULL default '000000000',
  `cancel_user_id` int(11) NOT NULL,
  `cancle_description` longtext NOT NULL,
  `bank_id` int(1) NOT NULL,
  `stock_code` varchar(255) NOT NULL,
  `stock_fullname` varchar(255) NOT NULL,
  `mem_bank_account` varchar(255) default NULL,
  `mem_bank_type` varchar(1) default '',
  `receipt_group_id` int(255) NOT NULL,
  PRIMARY KEY  (`receipt_id`),
  KEY `receipt_no` USING BTREE (`receipt_no`),
  KEY `acc_operate_id` USING BTREE (`acc_operate_id`),
  KEY `member_id` USING BTREE (`member_id`),
  KEY `receipt_type` USING BTREE (`receipt_type`),
  KEY `cancle_receipt_id` USING BTREE (`cancle_receipt_id`),
  KEY `cancle_operate_id` USING BTREE (`cancle_operate_id`),
  KEY `cancel_user_id` USING BTREE (`cancel_user_id`),
  KEY `branch_num` USING BTREE (`branch_num`),
  KEY `user_id` USING BTREE (`user_id`)
) ENGINE=MyISAM DEFAULT CHARSET=tis620;

