DROP TABLE IF EXISTS `mem_receipt_detail_true`;
CREATE TABLE `mem_receipt_detail_true` (
  `receipt_detail_id` int(11) NOT NULL auto_increment,
  `receipt_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `receipt_detail_no` int(11) NOT NULL COMMENT 'row in receipt',
  `item_code` varchar(255) NOT NULL,
  `receipt_detail_amount` double(30,4) NOT NULL,
  `receipt_detail_tax` double(30,4) NOT NULL,
  `timestamp` timestamp NOT NULL default CURRENT_TIMESTAMP on update CURRENT_TIMESTAMP,
  PRIMARY KEY  (`receipt_detail_id`)
) ENGINE=MyISAM DEFAULT CHARSET=tis620;

