--
-- Table structure for table `mem_register_true`
--

DROP TABLE IF EXISTS `mem_register_true`;
CREATE TABLE `mem_register_true` (
  `id_register` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `code_register` varchar(16) NOT NULL,
  `member_code` varchar(255) NOT NULL,
  `acc_operate_id` char(9) NOT NULL,
  `branch_num` char(2) NOT NULL,
  `flag` char(1) NOT NULL default '1' COMMENT '1=wait,2=submit,3=cancle',
  `stock_code` varchar(255) NOT NULL,
  `mem_font_name_id` int(11) NOT NULL,
  `member_name` varchar(100) NOT NULL,
  `member_surname` varchar(100) NOT NULL,
  `member_gender` int(1) NOT NULL,
  `member_marriage` int(1) NOT NULL,
  `member_idcard` varchar(13) NOT NULL,
  `member_birthday` date NOT NULL,
  `mem_group_mem_id` int(11) NOT NULL,
  `level_debtor_id` int(11) NOT NULL,
  `mem_job_name_id` int(11) NOT NULL,
  `member_address` varchar(50) NOT NULL,
  `member_mou` varchar(5) NOT NULL,
  `member_street` varchar(50) NOT NULL,
  `province_id` int(11) NOT NULL,
  `amphur_id` int(11) NOT NULL,
  `tumbon_id` int(11) NOT NULL,
  `member_zipcode` char(5) NOT NULL,
  `member_phone` char(25) NOT NULL,
  `member_fax` char(25) NOT NULL,
  `member_type` int(1) NOT NULL,
  `member_images` varchar(255) NOT NULL,
  `cancle_detail` longtext NOT NULL,
  `member_money` double(30,4) NOT NULL,
  `member_money2` double(30,4) NOT NULL,
  `member_limit` double(30,4) NOT NULL,
  `member_self_land` int(1) NOT NULL,
  `member_rent_land` int(1) NOT NULL,
  `member_other_land` int(1) NOT NULL,
  `self_land_1` int(3) NOT NULL,
  `self_land_2` int(1) NOT NULL,
  `self_land_3` int(2) NOT NULL,
  `rent_land_1` int(3) NOT NULL,
  `rent_land_2` int(1) NOT NULL,
  `rent_land_3` int(2) NOT NULL,
  `about_other_land` varchar(255) NOT NULL,
  `member_stock_start` date NOT NULL,
  `member_stock_billing` double(30,4) NOT NULL,
  `member_email` varchar(50) NOT NULL,
  `bank_account_type1_reference` varchar(100) default NULL,
  `bank_account_type1_number` varchar(100) default NULL,
  `bank_account_type2_number` varchar(100) default NULL,
  `marriage_font_name_id` int(11) NOT NULL default '0',
  `marriage_name` varchar(100) NOT NULL default '',
  `marriage_surname` varchar(100) NOT NULL default '',
  `member_son` int(5) NOT NULL default '0',
  `member_education` int(5) NOT NULL default '0',
  `member_education_other` varchar(100) NOT NULL default '',
  `nationality` varchar(50) NOT NULL,
  PRIMARY KEY  (`id_register`),
  KEY `code_register` USING BTREE (`code_register`),
  KEY `member_code` USING BTREE (`member_code`),
  KEY `acc_operate_id` USING BTREE (`acc_operate_id`),
  KEY `branch_num` USING BTREE (`branch_num`),
  KEY `mem_font_name_id` USING BTREE (`mem_font_name_id`),
  KEY `stock_code` USING BTREE (`stock_code`),
  KEY `mem_group_mem_id` USING BTREE (`mem_group_mem_id`),
  KEY `level_debtor_id` USING BTREE (`level_debtor_id`),
  KEY `mem_job_name_id` USING BTREE (`mem_job_name_id`),
  KEY `province_id` USING BTREE (`province_id`),
  KEY `amphur_id` USING BTREE (`amphur_id`),
  KEY `tumbon_id` USING BTREE (`tumbon_id`),
  KEY `member_stock_billing` USING BTREE (`member_stock_billing`)
) ENGINE=MyISAM DEFAULT CHARSET=tis620;

