-- Dumping data for table `mem_register_true`
--

LOCK TABLES `mem_register_true` WRITE;
/*!40000 ALTER TABLE `mem_register_true` DISABLE KEYS */;
/*!40000 ALTER TABLE `mem_register_true` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `mem_report_receipt`
--

DROP TABLE IF EXISTS `mem_report_receipt`;
CREATE TABLE `mem_report_receipt` (
  `report_id` int(11) NOT NULL auto_increment,
  `acc_operate_id` char(9) NOT NULL,
  `receipt_id` varchar(16) NOT NULL,
  `description` varchar(255) NOT NULL,
  `branch_num` char(2) NOT NULL,
  `user_id` int(10) NOT NULL,
  PRIMARY KEY  (`report_id`,`branch_num`),
  KEY `acc_operate_id` USING BTREE (`acc_operate_id`),
  KEY `receipt_id` USING BTREE (`receipt_id`),
  KEY `branch_num` USING BTREE (`branch_num`),
  KEY `user_id` USING BTREE (`user_id`)
) ENGINE=MyISAM AUTO_INCREMENT=30 DEFAULT CHARSET=tis620;

