--
-- Table structure for table `mem_resign`
--

DROP TABLE IF EXISTS `mem_resign`;
CREATE TABLE `mem_resign` (
  `resign_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `resign_no` varchar(255) NOT NULL,
  `acc_operate_id` char(9) NOT NULL default '000000000',
  `member_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `resign_status` int(11) NOT NULL COMMENT '1=à¸£à¸­à¸­à¸™à¸¸à¸¡à¸±à¸•à¸´ 2= à¸­à¸™à¸¸à¸¡à¸±à¸•à¸´ 3=à¸¢à¸à¹€à¸¥à¸´à¸',
  `resign_type` varchar(255) NOT NULL,
  `pay_date` varchar(10) default NULL,
  `stock_value` double(30,4) NOT NULL,
  `debt_amount` double(30,4) NOT NULL,
  `gua_amount` double(30,4) NOT NULL,
  `description` longtext NOT NULL,
  `branch_num` char(2) NOT NULL default '00',
  `user_id` int(10) NOT NULL,
  `receipt_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `amount_type` int(1) NOT NULL,
  `bank_id` varchar(20) NOT NULL,
  `receipt_person` varchar(255) NOT NULL,
  `submit_operate_id` char(9) NOT NULL default '000000000',
  `submit_resign_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `submit_user_id` int(10) NOT NULL,
  `export_status` int(1) NOT NULL COMMENT '1=ส่งออกแล้ว 0=ยังไม่มีการส่งออก',
  `cancel_resign_id` varchar(16) NOT NULL COMMENT '[prefix 3 digit][if have type_loan_id 3 digit][year 2 digit][branch_num 2 digit][auto 6 digit]',
  `cancel_operate_id` char(9) NOT NULL default '000000000',
  `cancel_user_id` int(10) NOT NULL,
  `cancle_description` longtext NOT NULL,
  PRIMARY KEY  (`resign_id`),
  KEY `resign_no` USING BTREE (`resign_no`),
  KEY `acc_operate_id` USING BTREE (`acc_operate_id`),
  KEY `member_id` USING BTREE (`member_id`),
  KEY `resign_status` USING BTREE (`resign_status`),
  KEY `receipt_id` USING BTREE (`receipt_id`),
  KEY `submit_operate_id` USING BTREE (`submit_operate_id`),
  KEY `submit_resign_id` USING BTREE (`submit_resign_id`),
  KEY `submit_user_id` USING BTREE (`submit_user_id`),
  KEY `cancel_resign_id` USING BTREE (`cancel_resign_id`),
  KEY `cancel_operate_id` USING BTREE (`cancel_operate_id`),
  KEY `cancel_user_id` USING BTREE (`cancel_user_id`),
  KEY `branch_num` USING BTREE (`branch_num`),
  KEY `user_id` USING BTREE (`user_id`)
) ENGINE=MyISAM DEFAULT CHARSET=tis620;

