  `amount_supply` double(30,4) NOT NULL,
  `amount_collect` double(30,4) NOT NULL,
  `amount_transform` double(30,4) NOT NULL,
  `amount_loan` double(30,4) default NULL COMMENT 'ธุรกิจสินเชื่อ',
  PRIMARY KEY  (`rpt_id`)
) ENGINE=MyISAM DEFAULT CHARSET=tis620;

