--
-- Table structure for table `temp_rpt_verified_accounts_receivable_list`
--

DROP TABLE IF EXISTS `temp_rpt_verified_accounts_receivable_list`;
CREATE TABLE `temp_rpt_verified_accounts_receivable_list` (
  `member_id` varchar(16) NOT NULL default '',
  `member_code` varchar(16) default NULL,
  `member_full_name` varchar(200) default NULL,
  `group_mem_id` varchar(4) default NULL,
  `member_loan_short_amount` double(30,4) NOT NULL,
  `member_loan_medium_amount` double(30,4) NOT NULL,
  `member_inventory_amount` double(30,4) NOT NULL,
  `member_deposit_amount` double(30,4) NOT NULL,
  `member_stock_amount` double(30,4) NOT NULL,
  `data_date` varchar(200) default NULL,
  `user_id` int(11) NOT NULL,
  `contract_loan` varchar(20) default '' COMMENT 'เงินกู้สัญญาเลขที่',
  `deposit_number` varchar(20) default '' COMMENT 'เงินฝากบัญชีเลขที่',
  `deposit_amount` double(30,4) default NULL COMMENT 'จำนวนเงินฝาก',
  PRIMARY KEY  (`member_id`)
) ENGINE=MyISAM DEFAULT CHARSET=tis620;

